<template>
  <view class="page">
    <view class="month"><text @click="changeMonth(-1)">‹</text><view><b>{{ monthLabel }}</b><small>选择交易日查看两融信号</small></view><text :class="{ disabled: !canNext }" @click="changeMonth(1)">›</text></view>
    <view class="week"><text v-for="day in ['日','一','二','三','四','五','六']" :key="day">{{ day }}</text></view>
    <view class="calendar"><view v-for="cell in days" :key="cell.key" :class="['day', { active: selectedDate === cell.date, marked: cell.count }]" @click="selectDate(cell.date)"><text>{{ cell.day }}</text><small v-if="cell.count">{{ cell.count }} 个</small></view></view>
    <view class="tabs"><text v-for="item in modes" :key="item.key" :class="{ active: mode === item.key }" @click="changeMode(item.key)">{{ item.label }}</text></view>
    <view v-if="mode === 'combo'" class="windows"><text v-for="day in [2,3,5]" :key="day" :class="{ active: windowDays === day }" @click="changeWindow(day)">{{ day }}日连续</text></view>
    <view class="headline"><text>{{ selectedDate ? `${selectedDate.slice(4, 6)}月${selectedDate.slice(6)}日 ${modeLabel}` : '请选择信号日' }}</text><button v-if="selectedDate" @click="loadDetail">刷新</button></view>
    <view v-if="loading" class="empty">正在读取两融信号…</view><view v-else-if="selectedDate && !rows.length" class="empty">该日暂无两融信号</view>
    <scroll-view v-else class="list" scroll-x><view class="table"><view class="table-head"><text>排名</text><text>股票</text><text>{{ strengthLabel }}</text><text v-for="day in returnDays" :key="day">T+{{ day }}</text></view><view v-for="(row, index) in rows" :key="row.stockCode" class="row" @click="openKline(row)"><text class="rank">{{ rank(row, index) }}</text><view class="stock"><text class="name">{{ row.stockName }}</text><text class="code">{{ row.stockCode }} · {{ row.industryName || '--' }}</text></view><text class="strength">{{ strength(row) }}</text><text v-for="day in returnDays" :key="day" :class="['return', returnValue(row, day) == null ? '' : returnValue(row, day) >= 0 ? 'up' : 'down']">{{ percent(returnValue(row, day)) }}</text></view></view></scroll-view>
  </view>
</template>

<script setup>
import { computed, ref } from "vue";
import { onShow } from "@dcloudio/uni-app";
import { getMarginCalendar, listMarginCombo, listMarginModels, listMarginSingle } from "@/api/stock/margin";
const now = new Date(), cursor = ref(new Date(now.getFullYear(), now.getMonth(), 1)), calendar = ref([]), selectedDate = ref(""), rows = ref([]), loading = ref(false), mode = ref("single"), windowDays = ref(2);
const modes = [{ key: "model", label: "模型" }, { key: "single", label: "单日" }, { key: "combo", label: "连续" }];
const monthKey = computed(() => `${cursor.value.getFullYear()}${String(cursor.value.getMonth() + 1).padStart(2, "0")}`), monthLabel = computed(() => `${cursor.value.getFullYear()} 年 ${cursor.value.getMonth() + 1} 月`), canNext = computed(() => cursor.value.getFullYear() < now.getFullYear() || cursor.value.getMonth() < now.getMonth()), modeLabel = computed(() => modes.find(item => item.key === mode.value)?.label || "两融"), returnDays = computed(() => mode.value === "model" ? [1, 3, 5, 10, 20] : [1, 2, 3, 4, 5]), strengthLabel = computed(() => mode.value === "model" ? "综合分" : mode.value === "single" ? "评分" : "累计分");
const days = computed(() => { const first = new Date(cursor.value.getFullYear(), cursor.value.getMonth(), 1).getDay(), count = new Date(cursor.value.getFullYear(), cursor.value.getMonth() + 1, 0).getDate(), signals = new Map(calendar.value.map(item => [item.tradeDate, item.signalCount])); return Array.from({ length: first + count }, (_, i) => { const day = i - first + 1, date = i < first ? "" : `${monthKey.value}${String(day).padStart(2, "0")}`; return { key: date || i, day: i < first ? "" : day, date, count: signals.get(date) || 0 }; }); });
const percent = value => value === null || value === undefined ? "--" : `${Number(value) >= 0 ? "+" : ""}${Number(value).toFixed(2)}%`;
function rank(row, index) { return row.rankNo || row.latestRank || index + 1; }
function strength(row) { return Number(mode.value === "combo" ? row.totalScore : row.score || 0).toFixed(1); }
function returnValue(row, day) { return mode.value === "model" ? row[`next${day}dReturnPct`] : row[`t${day}MaxReturnPct`]; }
function openKline(row) { const entryPrice = Number(row.entryPrice || 0), tradeDate = row.entryTradeDate || row.signalDate || row.tradeDate || selectedDate.value; if (entryPrice > 0 && tradeDate) uni.setStorageSync('stock-kline-context', { code: row.stockCode, entryPrice, tradeDate: String(tradeDate) }); uni.navigateTo({ url: `/pages/stock/kline?code=${row.stockCode}&name=${encodeURIComponent(row.stockName)}${entryPrice > 0 && tradeDate ? '&cost=1' : ''}` }); }
async function loadCalendar() { const response = await getMarginCalendar(monthKey.value, mode.value, mode.value === "combo" ? windowDays.value : undefined); calendar.value = response.data || []; if (!selectedDate.value && calendar.value.length) await selectDate(calendar.value[calendar.value.length - 1].tradeDate); }
async function selectDate(date) { if (!date || !calendar.value.some(item => item.tradeDate === date)) return; selectedDate.value = date; await loadDetail(); }
async function loadDetail() { if (!selectedDate.value) return; loading.value = true; try { const params = { startDate: selectedDate.value, endDate: selectedDate.value, pageNum: 1, pageSize: 200 }; const request = mode.value === "model" ? listMarginModels : mode.value === "single" ? listMarginSingle : listMarginCombo; if (mode.value === "combo") params.windowDays = windowDays.value; rows.value = ((await request(params)).data?.rows || []).sort((left, right) => Number(right.score ?? right.totalScore ?? 0) - Number(left.score ?? left.totalScore ?? 0)); } catch { rows.value = []; } finally { loading.value = false; } }
async function changeMonth(offset) { if (offset > 0 && !canNext.value) return; cursor.value = new Date(cursor.value.getFullYear(), cursor.value.getMonth() + offset, 1); selectedDate.value = ""; rows.value = []; await loadCalendar(); }
async function changeMode(value) { if (mode.value === value) return; mode.value = value; selectedDate.value = ""; rows.value = []; await loadCalendar(); }
async function changeWindow(value) { if (windowDays.value === value) return; windowDays.value = value; selectedDate.value = ""; rows.value = []; await loadCalendar(); }
onShow(loadCalendar);
</script>

<style scoped>
.page{min-height:100vh;background:#f5f7fb;padding:28rpx 30rpx}.month{display:flex;justify-content:space-between;align-items:center;background:#fff;border-radius:22rpx;padding:24rpx 30rpx;color:#264fc4}.month>text{font-size:50rpx}.month>text.disabled{color:#cbd3df}.month view{display:flex;flex-direction:column;align-items:center;color:#25324a}.month b{font-size:30rpx}.month small{font-size:20rpx;color:#8b96a8;margin-top:8rpx}.week,.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:8rpx}.week{margin:26rpx 0 12rpx}.week text{text-align:center;font-size:20rpx;color:#8b96a8}.day{min-height:92rpx;padding:12rpx 8rpx;box-sizing:border-box;background:#fff;border-radius:12rpx;font-size:23rpx;color:#8a96a8}.day.marked{color:#25324a;background:#eaf0ff}.day.active{background:#315bd4;color:#fff}.day small{display:block;margin-top:8rpx;font-size:17rpx}.tabs,.windows{display:flex;background:#fff;border-radius:16rpx;margin-top:24rpx}.tabs text{flex:1;padding:20rpx 0;text-align:center;font-size:24rpx;color:#8b96a8}.tabs .active{color:#315bd4;font-weight:700;border-bottom:4rpx solid #315bd4}.windows{gap:12rpx;padding:12rpx;margin-top:14rpx}.windows text{flex:1;text-align:center;padding:11rpx 0;border-radius:10rpx;background:#f3f5f9;color:#718097;font-size:22rpx}.windows .active{background:#e8edff;color:#315bd4}.headline{display:flex;justify-content:space-between;align-items:center;margin:28rpx 0 16rpx;font-size:30rpx;font-weight:700;color:#17233d}.headline button{margin:0;background:#edf1ff;color:#315bd4;border:0;font-size:22rpx}.list{background:#fff;border-radius:18rpx}.table{min-width:980rpx}.table-head,.row{display:grid;grid-template-columns:58rpx 280rpx 120rpx repeat(5,118rpx);align-items:center}.table-head{height:68rpx;background:#f8faff;color:#7d8a9e;font-size:20rpx}.table-head text{text-align:center}.row{min-height:102rpx;border-top:1rpx solid #edf0f6}.rank,.strength{text-align:center;font-size:22rpx;color:#68778d}.stock{min-width:0;padding:16rpx 8rpx}.name,.code{display:block}.name{font-size:26rpx;font-weight:650;color:#25324a}.code{font-size:18rpx;color:#8b96a8;margin-top:7rpx;white-space:nowrap}.return{text-align:center;font-size:24rpx;font-weight:700}.up{color:#e44848}.down{color:#18a56c}.empty{padding:48rpx 20rpx;text-align:center;border-radius:18rpx;background:#fff;color:#8b96a8;font-size:24rpx}
</style>
